import{c as r,Q as o,j as a,m as t}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function n(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Generated at build time from <a href="https://github.com/smazurov/videonode/blob/main/changelog.yml" target="_blank" rel="noreferrer"><code>changelog.yml</code></a>. Cross-reference <a href="https://github.com/smazurov/videonode/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for download links and signed artifacts.</p><h2 id="_4-0-0-rc10" tabindex="-1">4.0.0-rc10 <a class="header-anchor" href="#_4-0-0-rc10" aria-label="Permalink to &quot;4.0.0-rc10&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>rkmpp encoders ingest BGRA/RGB32 directly, converting in hardware instead of via a CPU-heavy software nv12 filter (<a href="https://github.com/smazurov/videonode/commit/7e869b2" target="_blank" rel="noreferrer"><code>7e869b2</code></a>)</li><li>readers dialing a stream that isn&#39;t configured now get a clean 404 instead of a logged warning and a spawned encoder (<a href="https://github.com/smazurov/videonode/commit/89b821e" target="_blank" rel="noreferrer"><code>89b821e</code></a>)</li><li>the .deb ships the videonode asound.conf so the RK3588 audio capture config is present on install (<a href="https://github.com/smazurov/videonode/commit/e533874" target="_blank" rel="noreferrer"><code>e533874</code></a>)</li></ul><h2 id="_4-0-0-rc9" tabindex="-1">4.0.0-rc9 <a class="header-anchor" href="#_4-0-0-rc9" aria-label="Permalink to &quot;4.0.0-rc9&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>WHEP egress endpoint (POST/DELETE /whep/{stream}) for WebRTC playback, with working H265 and a fix for motion smearing (<a href="https://github.com/smazurov/videonode/commit/f412934" target="_blank" rel="noreferrer"><code>f412934</code></a>)</li><li>WebRTC peers and SRT consumers now share a single hex client-ID scheme (<a href="https://github.com/smazurov/videonode/commit/cde5b5c" target="_blank" rel="noreferrer"><code>cde5b5c</code></a>)</li></ul><h2 id="_4-0-0-rc8" tabindex="-1">4.0.0-rc8 <a class="header-anchor" href="#_4-0-0-rc8" aria-label="Permalink to &quot;4.0.0-rc8&quot;">​</a></h2><p><em>2026-05-30</em></p><ul><li>RK3588 audio capture reworked: routed through an mmap plug-&gt;dsnoop PCM that converts the card-native format (the Hollyland Lyra is S32_LE-only) to whatever the encoder requests, with a larger dsnoop ring to kill xruns under the 1080p60 transcode load (opus output ~8kbps silence -&gt; ~85kbps); the service unit gains the audio group and streams now honor per-stream audio config (<a href="https://github.com/smazurov/videonode/commit/de9c2d1" target="_blank" rel="noreferrer"><code>de9c2d1</code></a>)</li><li>native source/sink robustness: the source gates NV12 ring reuse on consumer read-completion (per-slot refcount + generation), fixing the venetian-blind tearing seen across snapshot, composer, and encoder output; vn-sink reconnects across a source/composer restart instead of feeding a dead RTSP relay; the composer fails fast on a GPU-less host (<a href="https://github.com/smazurov/videonode/commit/661e15c" target="_blank" rel="noreferrer"><code>661e15c</code></a>)</li><li>hardware MJPEG decode adopts MPP&#39;s info-change handshake (two buffer groups, packet-owned input, one-shot SET_INFO_CHANGE_READY), fixing the per-frame jpegd reset that left Lyra MJPEG frames undecoded (<a href="https://github.com/smazurov/videonode/commit/975e2d3" target="_blank" rel="noreferrer"><code>975e2d3</code></a>)</li><li>SSE entity payload is typed end-to-end as a oneOf+discriminator keyed on a <code>type</code> tag, so the UI narrows on event.type with no casts; idle now publishes a full zeroed status, so partial payloads can no longer crash the source panel (<a href="https://github.com/smazurov/videonode/commit/56558e4" target="_blank" rel="noreferrer"><code>56558e4</code></a>)</li><li>connection robustness: the UI detects a dead rig in ~20s via an 8s request timeout and a 20s SSE heartbeat watchdog instead of waiting out the TCP timeout, the shared SSE connection persists across navigation, reconnect is health-gated, and offline stats blank to dimmed em-dashes instead of frozen fake-ticking values (<a href="https://github.com/smazurov/videonode/commit/02dcb7a" target="_blank" rel="noreferrer"><code>02dcb7a</code></a>)</li><li>unified POST /api/processes/{id}/restart for source/composer/encoder, with restart buttons on the detail pages (<a href="https://github.com/smazurov/videonode/commit/3b5bfba" target="_blank" rel="noreferrer"><code>3b5bfba</code></a>)</li><li>the .deb no longer hard-depends on out-of-band board libraries (librga2, librockchip-mpp1) that come from a 3rd-party repo or a from-source build, fixing uninstallable &#39;apt install videonode&#39; where no owning package exists (<a href="https://github.com/smazurov/videonode/commit/c38e3bc" target="_blank" rel="noreferrer"><code>c38e3bc</code></a>)</li></ul><h2 id="_4-0-0-rc7" tabindex="-1">4.0.0-rc7 <a class="header-anchor" href="#_4-0-0-rc7" aria-label="Permalink to &quot;4.0.0-rc7&quot;">​</a></h2><p><em>2026-05-29</em></p><ul><li>composer layout editor rebuilt on a Region/Content model: Region is the axis-aligned output rectangle, Content the rotatable source overlay (0/90/180/270, cover/fit/stretch, pan/zoom), fixing rotated-slot resize at the root; edits now persist while the pipeline is idle (<a href="https://github.com/smazurov/videonode/commit/c1a4d04" target="_blank" rel="noreferrer"><code>c1a4d04</code></a>)</li><li>real-time updates collapse onto a single entity-envelope SSE stream, replacing the legacy per-event publishes; consumer-set changes fire a dedicated source.consumers event only on membership change (<a href="https://github.com/smazurov/videonode/commit/8275702" target="_blank" rel="noreferrer"><code>8275702</code></a>)</li><li>operational UI: infobar shows live pipeline uptime/CPU/mem via a new daemon resource endpoint, source list shows format/res/fps and live consumer count, and the header tints with no thrown errors when the backend connection drops (<a href="https://github.com/smazurov/videonode/commit/22fbdd1" target="_blank" rel="noreferrer"><code>22fbdd1</code></a>)</li><li>hardware MJPEG decode now works, driven through MPP&#39;s advanced 1-in-1-out path with input-buffer sync (the prior simple-API loop never produced a frame); adds an mpp-jpeg-probe diagnostic (<a href="https://github.com/smazurov/videonode/commit/cea24f4" target="_blank" rel="noreferrer"><code>cea24f4</code></a>)</li><li>source/capture robustness: reports no-signal when the device is absent, stops busy-spinning on capture-fd errors, stamps status with wall-clock time, and keeps the encoder idle until a reader connects (rebuilding it on a dimension change) (<a href="https://github.com/smazurov/videonode/commit/4b21ceb" target="_blank" rel="noreferrer"><code>4b21ceb</code></a>)</li><li>release target moves to Debian 13 (trixie) so the composer libplacebo backend builds; .deb runtime deps are derived from the real binaries via dpkg-shlibdeps, and installs on bookworm now fail with a readable apt error (<a href="https://github.com/smazurov/videonode/commit/7720917" target="_blank" rel="noreferrer"><code>7720917</code></a>)</li></ul><h2 id="_4-0-0-rc6" tabindex="-1">4.0.0-rc6 <a class="header-anchor" href="#_4-0-0-rc6" aria-label="Permalink to &quot;4.0.0-rc6&quot;">​</a></h2><p><em>2026-05-29</em></p><ul><li>arm64 .deb builds on Debian bookworm and declares its native runtime libraries (gRPC, protobuf, abseil, libplacebo, turbojpeg), fixing missing-shared-object and GLIBCXX-version failures on bookworm/Armbian SBCs (<a href="https://github.com/smazurov/videonode/commit/0e467ef" target="_blank" rel="noreferrer"><code>0e467ef</code></a>)</li></ul><h2 id="_4-0-0-rc5" tabindex="-1">4.0.0-rc5 <a class="header-anchor" href="#_4-0-0-rc5" aria-label="Permalink to &quot;4.0.0-rc5&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>streams drop configurable publish targets: encoders publish to the built-in local RTSP relay, SRT/WebRTC fan out from there (breaking) (<a href="https://github.com/smazurov/videonode/commit/3ccdfaf" target="_blank" rel="noreferrer"><code>3ccdfaf</code></a>)</li><li>remove the in-app self-update service; updates ship via the .deb / APT repo only (breaking) (<a href="https://github.com/smazurov/videonode/commit/1de2fe0" target="_blank" rel="noreferrer"><code>1de2fe0</code></a>)</li><li>sources expose a liveness signal distinct from status, surfaced with per-entity log panels over the shared SSE stream (<a href="https://github.com/smazurov/videonode/commit/d5d9270" target="_blank" rel="noreferrer"><code>d5d9270</code></a>)</li><li>stream editing UI: partial-PATCH edits and auto-start preview that wakes an idle stream (<a href="https://github.com/smazurov/videonode/commit/4676230" target="_blank" rel="noreferrer"><code>4676230</code></a>)</li><li>pipeline fixes: compositor honors the NV12 UV-plane offset, source pins and reports the real capture rate via G_PARM (<a href="https://github.com/smazurov/videonode/commit/47767b1" target="_blank" rel="noreferrer"><code>47767b1</code></a>)</li><li>packaging cleanup: drop the legacy install.sh and the network-online unit dependency (<a href="https://github.com/smazurov/videonode/commit/321b127" target="_blank" rel="noreferrer"><code>321b127</code></a>)</li></ul><h2 id="_4-0-0-rc4" tabindex="-1">4.0.0-rc4 <a class="header-anchor" href="#_4-0-0-rc4" aria-label="Permalink to &quot;4.0.0-rc4&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>packaging: enroll SUDO_USER on upgrade, not just first install (<a href="https://github.com/smazurov/videonode/commit/37f0656" target="_blank" rel="noreferrer"><code>37f0656</code></a>)</li></ul><h2 id="_4-0-0-rc3" tabindex="-1">4.0.0-rc3 <a class="header-anchor" href="#_4-0-0-rc3" aria-label="Permalink to &quot;4.0.0-rc3&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>VitePress docs site with Mermaid, search, versioned navbar (<a href="https://github.com/smazurov/videonode/commit/cdd37c1" target="_blank" rel="noreferrer"><code>cdd37c1</code></a>)</li><li>release pipeline rewrite: matrix build replaces goreleaser, chglog-driven .deb (<a href="https://github.com/smazurov/videonode/commit/feff078" target="_blank" rel="noreferrer"><code>feff078</code></a>)</li><li>shadow-group-gated auth + postinst enrollment, service auto-start on install (<a href="https://github.com/smazurov/videonode/commit/f62e5a3" target="_blank" rel="noreferrer"><code>f62e5a3</code></a>)</li><li>composer UI: auto-slot on input add, canvas rotation moved to inspector (<a href="https://github.com/smazurov/videonode/commit/74749ac" target="_blank" rel="noreferrer"><code>74749ac</code></a>)</li><li>source reports placeholder dims while V4L2 inactive (<a href="https://github.com/smazurov/videonode/commit/16f5389" target="_blank" rel="noreferrer"><code>16f5389</code></a>)</li></ul><h2 id="_4-0-0-rc1" tabindex="-1">4.0.0-rc1 <a class="header-anchor" href="#_4-0-0-rc1" aria-label="Permalink to &quot;4.0.0-rc1&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>feat(packaging): unified .deb via nfpm + GitHub Pages APT repo (<a href="https://github.com/smazurov/videonode/commit/c57d69e" target="_blank" rel="noreferrer"><code>c57d69e</code></a>)</li><li>refactor(packaging): replace CPack with nfpm (<a href="https://github.com/smazurov/videonode/commit/72c5d66" target="_blank" rel="noreferrer"><code>72c5d66</code></a>)</li></ul><h2 id="_3-1-0" tabindex="-1">3.1.0 <a class="header-anchor" href="#_3-1-0" aria-label="Permalink to &quot;3.1.0&quot;">​</a></h2><p><em>2026-05-18</em></p><ul><li>feat: v3.1.0 release (<a href="https://github.com/smazurov/videonode/commit/676bf30" target="_blank" rel="noreferrer"><code>676bf30</code></a>)</li></ul>',32)])])}const p=r(i,[["render",n]]);export{u as __pageData,p as default};
